MD_OUT = REPO_ROOT / "docs" / "architecture" / "rule-catalog.md"

BANNER = (
    "// Copyright Amazon.com, Inc. or its affiliates. All Rights Reserved.\n"
    "// SPDX-License-Identifier: MIT-0\n"
    "\n"
    "// GENERATED by scripts/render_catalog.py from src/catalog/engines/*.toml -- do not edit.\n"
    "// Change the engine's TOML file, then run: uv run python scripts/render_catalog.py\n"
)


def _js_string(value: str) -> str:
    # Single-quoted, the repo's JS style; json.dumps does the escaping.
    return "'" + json.dumps(value)[1:-1].replace("'", "\\'") + "'"


def _object(name: str, doc: str, rows: list[tuple[str, str]]) -> str:
    body = "".join(f"  {key}: {_js_string(value)},\n" for key, value in rows)
    return f"// {doc}\nexport const {name} = {{\n{body}}};\n"


def render_js(entries: tuple[EngineEntry, ...]) -> str:
    """The generated module's full text for ``entries`` (in catalog display order)."""
    cache_ids = sorted(engine_ids(status=ACTIVE, role="cache"))
    parts = [
        BANNER,
        _object(
            "ENGINE_LABELS",
            "Display name per engine id (display_name).",
            [(e.id, e.display_name) for e in entries],
        ),
        _object(
            "ENGINE_HEX",
            "Live UI colour per engine id (colors.ui).",
            [(e.id, e.colors.ui) for e in entries],
        ),
        "// Every engine id in the assignment gate's picker order (ui_picker_order).\n"
        "export const ENGINE_PICKER_ORDER = ["
        + ", ".join(_js_string(e.id) for e in sorted(entries, key=lambda e: e.ui_picker_order))
        + "];\n",
        '// Active engines whose role is a cache layer (role = "cache").\n'
        f"export const CACHE_ENGINE_IDS = [{', '.join(_js_string(i) for i in cache_ids)}];\n",
        _object(
            "ENGINE_STATUS",
            "Catalog status per engine id (status): active is a routing target, future a"
            " named placeholder (ADR-031 Decision 9), legacy an id only older reports carry.",
            [(e.id, e.status) for e in entries],
        ),
    ]
    return "\n".join(parts)


def _cell(support: EngineSupport | None) -> str:
    """The matrix cell for one engine's entry: what it does to a query's score."""
    if support is None:
        return "missing"
    if support.kind == "fit":
        return (
            f"fit {support.score}" if support.score is not None else f"fit ({support.confidence})"
        )
    if support.kind == "anti_pattern":
        return f"anti {support.severity:g}" + ("" if support.supported else ", no")
    if support.kind == "redesign":
        return f"redesign -{support.penalty}"
    if support.kind == "scan":
        return "scan"
    if support.kind == "future":
        return "future"
    if support.kind == "penalized":
        return "**no**"
    if not support.supported:
        return "no"
    return {"native": "native", "unscored": "-"}[support.kind]


def _engine_columns(entries: tuple[EngineEntry, ...]) -> list[EngineEntry]:
    """The engines a pattern file has an entry for: every engine routing can target, then
    the future-enhancement placeholders."""
    decided = engine_ids(status=(*ACTIVE, "future"))
    return [e for e in entries if e.id in decided]


def render_md(entries: tuple[EngineEntry, ...], pattern_entries: tuple[PatternEntry, ...]) -> str:
    """The rule-catalog Markdown page for ``entries`` and ``pattern_entries``."""
    columns = _engine_columns(entries)
    out = [
        "# Rule catalog: patterns x engines",
        "",
        "<!-- GENERATED by scripts/render_catalog.py from src/catalog/ -- do not edit. -->",
        "",
        "Generated from `src/catalog/engines/*.toml`, `src/catalog/patterns/*.toml`, "
        "`src/catalog/routing.toml`, `src/catalog/gates.toml` and "
        "`src/catalog/triage_signals.toml` (ADR-031 Decision 8). Change a TOML file, then run "
        "`uv run python scripts/render_catalog.py`. Field definitions: "
        "`src/shared/catalog/engines.py`, `src/shared/catalog/patterns.py` and "
        "`src/shared/catalog/routing.py`.",
        "",
        "**Compatibility.** The TOML format (file locations, table and key names, value "
        "types, which keys are required) is backwards compatible within 0.x: a release may "
        "add keys and files, but does not remove, rename or retype one without a documented "
        "deprecation first (`tests/contract/catalog_format_snapshot.json`, #1647). Rule ids "
        "(the engine, pattern, gap rule and write intent files, and named entries such as "
        "thresholds and signals) are stable; retiring one needs a deprecation. The values on "
        "this page (scores, penalties, prices, thresholds) are routing tuning and change "
        "between releases; each release's notes list the values that moved. Read them from "
        "the catalog files; do not hard-code them.",
        "",
        "## Engines",
        "",
        "| Engine | Id | Status | Role | System of record |",
        "|---|---|---|---|---|",
    ]
    for e in entries:
        status = "future enhancement" if e.status == "future" else e.status
        out.append(
            f"| {md_cell(e.display_name)} | `{e.id}` | {status} | {e.role} | "
            f"{'yes' if e.system_of_record else 'no'} |"
        )
    out += [
        "",
        "## Score weights",
        "",
        "How each engine weighs a query's four score dimensions (ADR-031 Decision 5), from "
        "its `[score_weights.<profile>]` tables; the first profile is the engine's default, "
        "and an engine with none uses the default split. Every engine gives cost the same "
        "weight (#1002).",
        "",
        "| Engine | Profile | Pattern match | Complexity | Performance | Cost |",
        "|---|---|---|---|---|---|",
    ]
    weighted = [(e.display_name, name, w) for e in entries for name, w in e.score_weights.items()]
    for label, name, w in [*weighted, ("Any other engine", "default", default_score_weights())]:
        shares = " | ".join(f"{round(w[d] * 100)}%" for d in SCORE_DIMENSIONS)
        out.append(f"| {md_cell(label)} | {name} | {shares} |")
    out += _routing_sections(entries)
    out += [
        "",
        "## Pattern x engine matrix",
        "",
        "Each cell is what a query showing the pattern gets on that engine: `fit N` (the "
        "engine's analysis reports it, catalog score N), `fit (level)` (reported with a "
        "confidence level instead of a score), `anti S` (reported as an anti-pattern, "
        "severity S), `native` (has the capability, never penalised), `scan` (lacks it and "
        "runs the pattern as a scan: loses the pattern's penalty only on a query that "
        "crosses its scan threshold), `redesign -N` "
        "(lacks it, bounded redesign, N-point penalty), **no** (cannot run it: takes the "
        "full penalty when another engine reports it as a fit), `no` (cannot run it, no "
        "score effect; `anti S, no` for a reported anti-pattern), `-` (no effect) or "
        "`future` (a future-enhancement placeholder: not modelled yet, never a routing "
        "candidate). "
        "Penalty is the points lost on an engine that reports it as an anti-pattern, or "
        "on every other engine when one reports it as a fit. One rule sizes it (ADR-031 "
        "Decision 8 Amendment 6): the penalty basis, the consequence the engines' public "
        "documentation states for the pattern, fixes the points ("
        + ", ".join(f"`{basis}` {points}" for basis, points in PENALTY_POINTS.items())
        + ").",
        "",
        "| Pattern | "
        + " | ".join(
            md_cell(e.display_name + (" (future)" if e.status == "future" else "")) for e in columns
        )
        + " | Penalty | Capability | Triage signal | Detectors |",
        "|---|" + "---|" * len(columns) + "---|---|---|---|",
    ]
    for p in pattern_entries:
        cells = [_cell(p.engines.get(e.id)) for e in columns]
        penalty = str(p.penalty) if p.penalty else "-"
        if p.penalty_basis:
            penalty += f" `{p.penalty_basis}`"
        if p.penalty_aliases:
            penalty += " (also " + ", ".join(f"`{a}`" for a in p.penalty_aliases) + ")"
        out.append(
            f"| [`{p.id}`](#{p.id}) | "
            + " | ".join(cells)
            + f" | {penalty} | {p.capability or '-'} | {p.triage_signal or '-'} | "
            f"{len(p.detectors) or 'none'} |"
        )
    out += ["", "## Patterns", ""]
    for p in pattern_entries:
        out += [f"### {p.id}", "", f"Name: {md_text(p.name)}."]
        if p.detectors:
            out.append("Detected by " + ", ".join(f"`{d}`" for d in p.detectors) + ".")
        else:
            out.append("No analysis reports this pattern today.")
        if p.penalty_why:
            out.append(f"Penalty: {p.penalty} (`{p.penalty_basis}`). {md_text(p.penalty_why)}")
        for label, note in (("Exemption note", p.exempt_note), ("Redesign note", p.redesign_note)):
            if note:
                out.append(f"{label}: {md_text(note)}")
        if p.scan_threshold:
            t = p.scan_threshold
            out.append(
                f"Scan threshold: {t.min_calls_per_second:g} calls per second and "
                f"{t.min_table_rows:,} table rows, both reached. {md_text(t.why)}"
            )
        if p.segment_weighting == "per_table":
            out.append(
                "Segment weighting: per table. A table's score weighs this pattern by the "
                "calls of the segment's queries that access that table, not the whole segment."
            )
        if p.write_pattern:
            out.append(
                "Writes only: no parity anchor borrows from it and no access class lists it."
            )
        out.append("")
        quiet: list[str] = []
        future: list[str] = []
        for e in columns:
            support = p.engines.get(e.id)
            if support is None:
                out.append(f"- {md_text(e.display_name)}: missing")
                continue
            if support.kind == "unscored" and support.class_score is None:
                quiet.append(e.display_name)
                continue
            if support.kind == "future":
                future.append(e.display_name)
                continue
            ref = f" ({support.catalog_id})" if support.catalog_id else ""
            if support.class_score is not None:
                ref += f", class score {support.class_score}"
                if support.parity_anchor:
                    ref += f" (parity anchor, from `{support.parity_anchor}`)"
            line = (
                f"- {md_text(e.display_name)}, {_cell(support).replace('**', '')}{ref}: "
                f"{md_text(support.why)}"
            )
            if support.guidance and support.kind in ("native", "scan"):
                line += f" Word search: {md_text(support.guidance)}"
            if bonus := _bonus_text(support):
                line += f" {bonus}"
            out.append(line)
        if quiet:
            out.append(f"- No effect on: {md_text(', '.join(quiet))}.")
        if future:
            out.append(f"- Not modelled yet (future enhancement): {md_text(', '.join(future))}.")
        out.append("")
    out += render_gaps_md(
        gap_rules(), aurora_version_lines(), {e.id: e.display_name for e in entries}
    )
    out += render_routine_checks_md(routine_check_rules(), {e.id: e.display_name for e in entries})
    out += render_routine_rewrites_md(
        routine_rewrite_rules(), {e.id: e.display_name for e in entries}
    )
    out += render_write_intents_md(
        write_intents(),
        carried_write_settings(),
        [e.id for e in _engine_columns(entries)],
        {e.id: e.display_name for e in entries},
    )
    return "\n".join(out).rstrip("\n") + "\n"


def render_write_intents_md(
    intents: tuple[WriteIntent, ...],
    settings: CarriedWriteSettings,
    engine_order: list[str],
    labels: dict[str, str],
) -> list[str]:
    """The write-intent section of the rule-catalog page (#1362)."""
    floor = settings.thresholds["carried_write_fit_floor"]
    out = [
        "## Write intents: serving a carried write the target's way",
        "",
        "Generated from `src/catalog/write_intents/*.toml` and `src/catalog/carried_writes.toml` "
        "(#1362; field definitions: `src/shared/catalog/write_intents.py`). A write group "
        "moves as one unit (ADR-031 Decision 1 Amendment 9), so it can carry a member whose "
        "own score on the group's engine is low. Below the floor, the member's intent is read "
        "from its parsed facts (`src/agents/referee/carried_writes.py`) and the designer input "
        "and the risk register name the engine's approach below; routing never reads it.",
        "",
        f"- `carried_write_fit_floor` = {floor.value}: {md_text(floor.why)}",
        "",
        "| Intent | What it is for |",
        "|---|---|",
    ]
    for intent in intents:
        out.append(f"| [`{intent.id}`](#{intent.id}) | {md_cell(intent.summary)} |")
    out.append("")
    for intent in intents:
        out += [
            f"### {intent.id}",
            "",
            f"{md_text(intent.name)}: {md_text(intent.summary)}",
            "",
            "| Engine | Approach | Documentation |",
            "|---|---|---|",
        ]
        for engine in [e for e in engine_order if e in intent.engines]:
            entry = intent.engines[engine]
            out.append(
                f"| {md_cell(labels.get(engine, engine))} | {md_cell(entry.approach)} | "
                f"{md_cell(entry.docs)} |"
            )
        out.append("")
    return out


