def _codes(values: tuple[str, ...]) -> str:
    return ", ".join(f"`{v}`" for v in values)


# The PostgreSQL checks that read a routine's body (#1951), and what they say when they
# cannot read it.
_PG_BODY_CHECKS = frozenset(
    {
        "function_call",
        "catalog_column",
        "public_schema_create",
        "setting",
        "type_use",
        "maintenance_search_path",
    }
)
_PG_BODY_UNKNOWN = (
    "; a body that does not parse, or one with dynamic SQL (EXECUTE) and no finding, is " "unknown"
)


def _routine_check_text(rule: RoutineCheckRule) -> str:
    """What a routine check rule checks, as one Markdown line."""
    text = _routine_check_words(rule)
    return text + _PG_BODY_UNKNOWN if rule.match.check in _PG_BODY_CHECKS else text


def _routine_check_words(rule: RoutineCheckRule) -> str:
    """What a routine check rule checks, before the body-read note."""
    match = rule.match
    if match.check == "parse":
        return "; ".join(_ROUTINE_PARSE_TEXT[e] for e in rule.source_engines)
    if match.check == "function_call":
        return (
            "a body call to " + _codes(match.called_functions) + " (unqualified or in "
            "pg_catalog)"
        )
    if match.check == "setting":
        return (
            "a SET, RESET or SHOW of " + _codes(match.removed_settings) + " in the body or "
            "the function's own SET clause, or a current_setting() / set_config() of it"
        )
    if match.check == "type_use":
        return "a parameter, return, cast, column or declared variable of type " + _codes(
            match.removed_types
        )
    if match.check == "catalog_column":
        return (
            "a body statement that reads " + _codes(match.catalog_columns) + " (the catalog "
            "relation unqualified, in pg_catalog or in information_schema)"
        )
    if (text := _ROUTINE_CHECK_TEXT.get(match.check)) is not None:
        return text
    if match.check == "definer":
        text = (
            "a DEFINER naming a user other than the target user (a CURRENT_USER form "
            "passes), for a routine that runs as its definer: a procedure or function "
            "unless it is SQL SECURITY INVOKER"
        )
        if match.always_definer_kinds:
            text += ", and always a " + " or ".join(match.always_definer_kinds)
        return text
    if match.check == "statement":
        parts = []
        if match.statement_starts:
            parts.append("a body statement that starts with " + _codes(match.statement_starts))
        if match.statement_contains:
            text = "a body statement that contains " + _codes(match.statement_contains)
            if match.statement_exceptions:
                text += " (not " + _codes(match.statement_exceptions) + ")"
            parts.append(text)
        if match.set_scopes:
            parts.append("a SET of a " + _codes(match.set_scopes) + " variable")
        if match.set_variables:
            parts.append("a SET of " + _codes(match.set_variables))
        if match.system_variables:
            parts.append("a SET or an `@@` read of " + _codes(match.system_variables))
        if match.function_calls:
            parts.append("a call to " + _codes(match.function_calls))
        return "; ".join(parts) + "; a prepared statement's literal text counts too"
    if match.check == "reserved_word":
        text = (
            "one of " + _codes(match.reserved_words) + " written as an unquoted identifier "
            "after the routine's name (a parameter, variable, label, column or table name; "
            "not after a `.`, not an `@` or `@@` variable), a prepared statement's literal "
            "text included"
        )
        if match.reserved_word_contexts:
            text += "; not inside " + _codes(match.reserved_word_contexts)
        return text
    if match.check == "group_by":
        if match.group_by == "without_order_by":
            return (
                "a SELECT (a cursor's included) whose own GROUP BY has no ORDER BY after it "
                "at the same level, or a GROUP BY at any level with a LIMIT and no ORDER BY "
                "at its level (a grouped subquery, an INSERT ... SELECT)"
            )
        return "a GROUP BY that sorts its columns with `ASC` or `DESC`, at any level"
    if match.check == "sql_mode":
        if match.unknown_sql_modes:
            return "a stored sql_mode holding a mode no other rule names and MySQL does not list"
        return "a stored sql_mode holding " + _codes(match.sql_modes)
    text = (
        "the metadata's language and the statement's LANGUAGE agree, and the language is "
        + " or ".join(f"`{v}`" for v in match.languages)
    )
    if match.trusted_extension_languages:
        text += (
            ", or one of "
            + ", ".join(f"`{v}`" for v in match.trusted_extension_languages)
            + " where the target version line offers it as an extension"
        )
    return text + "; any other language fails"


def _version_change_text(rule: RoutineCheckRule) -> str:
    """When a version-change rule runs (#1952), as a sentence for its row; empty for any
    other rule."""
    if rule.version_change is None:
        return ""
    line = rule.version_change.line
    return (
        f"; runs only when the source's version line is older than {line} and the target "
        f"line is {line} or later (never on a same-major target; an unknown source version "
        "is unknown, never a pass)"
    )


def _routine_check_claim(rule: RoutineCheckRule) -> str:
    """The claim marker of a rule's row: its engine's checker tests for its check (and, for
    a version-change rule, the tests of when it runs)."""
    if rule.source_engines == ("postgresql",):
        tests = _ROUTINE_CHECK_CLAIMS[rule.match.check]
        if rule.version_change is not None:
            return _claim((*tests, *_PG_VERSION_CHANGE_CLAIM))
    elif rule.source_engines == ("mysql",):
        tests = _MYSQL_ROUTINE_CHECK_CLAIMS[rule.match.check]
        if rule.match.check == "statement" and rule.version_change is not None:
            tests = (*tests, *_MYSQL_VERSION_STATEMENT_CLAIM)
    else:
        return ""
    if rule.version_change is not None:
        tests = (*tests, *_VERSION_CHANGE_CLAIM)
    return _claim(tests)


def render_routine_checks_md(
    rules: tuple[RoutineCheckRule, ...], labels: dict[str, str]
) -> list[str]:
    """The routine check rules section of the rule-catalog page (#1935, #1936)."""
    out = [
        "## Routine checks: what stops a routine loading on the target",
        "",
        "Generated from `src/catalog/routine_checks/*.toml` (#1935; field definitions: "
        "`src/shared/catalog/routine_checks.py`). Each routine's CREATE statement and "
        "metadata are checked against every rule for its kind; the verdict lists each "
        "rule's outcome with its reason and fix hint, runs the metadata checks even when "
        "the statement does not parse, and never holds the routine's statement or its literals."
        + _claim(_ROUTINE_SECTION_CLAIM)
        + " The target version line is the one the gap check's move lands on for the "
        "source's installed extensions."
        + _claim(_ROUTINE_LINE_CLAIM)
        + " A rule with a version change (#1952) checks what a newer major version changed: "
        "it runs only when the source's version line is older than that version and the "
        "target line has it, so never on a same-major target, and its outcome is unknown, "
        "never a pass, when the source's version is unknown."
        + _claim((*_VERSION_CHANGE_CLAIM, *_PG_VERSION_CHANGE_CLAIM))
        + " A caller of the library can check a PostgreSQL routine against the newest listed "
        "Aurora PostgreSQL line instead (#1951); the same-major choice stays the default, "
        "and no customer-facing choice exists yet (#2028)." + _claim(_TARGET_CHOICE_CLAIM),
        "",
        "| Rule | Sources | Targets | Kinds | Impact | Checks |",
        "|---|---|---|---|---|---|",
    ]
    for r in rules:
        targets = ", ".join(labels.get(t, t) for t in r.targets)
        out.append(
            f"| [`{r.id}`](#{r.id}) | {', '.join(r.source_engines)} | {md_cell(targets)} | "
            f"{', '.join(r.kinds)} | {_IMPACT_LABELS[r.impact]} | "
            f"{md_cell(_routine_check_text(r) + _version_change_text(r))}"
            f"{_routine_check_claim(r)} |"
        )
    out.append("")
    for r in rules:
        out += [
            f"### {r.id}",
            "",
            f"{md_text(r.feature)}: {_IMPACT_LABELS[r.impact].lower()}. {md_text(r.reason)}",
            "",
            f"Fix: {md_text(r.fix_hint)}",
            "",
            f"Documentation: {md_text(r.docs)}.",
            "",
        ]
    return out


