def render_routine_rewrites_md(
    rules: tuple[RoutineRewriteRule, ...], labels: dict[str, str]
) -> list[str]:
    """The routine rewrite rules section of the rule-catalog page (#1937)."""
    out = [
        "## Routine rewrites: what changes on its own",
        "",
        "Generated from `src/catalog/routine_rewrites/*.toml` (#1937; field definitions: "
        "`src/shared/catalog/routine_rewrites.py`). Each rewrite changes a routine's header "
        "only, never its body; each is recorded with its rule, its reason and a diff that "
        "never holds a literal, and a routine that still fails a check after its rewrites "
        "still needs attention."
        + _claim(_REWRITE_SECTION_CLAIM)
        + " A rewrite may still change how the routine runs, as each row says: a DEFINER or "
        "owner rewrite makes a routine that runs as its definer run with the target user's "
        "privileges, which its record notes, and a search_path pin keeps the source's name "
        "resolution even for a caller whose path differs." + _claim(_REWRITE_NOTE_CLAIM),
        "",
        "| Rule | Sources | Targets | Kinds | Rewrites | Resolves |",
        "|---|---|---|---|---|---|",
    ]
    for r in rules:
        targets = ", ".join(labels.get(t, t) for t in r.targets)
        resolves = ", ".join(f"[`{c}`](#{c})" for c in r.match.resolves) or "-"
        out.append(
            f"| [`{r.id}`](#{r.id}) | {', '.join(r.source_engines)} | {md_cell(targets)} | "
            f"{', '.join(r.kinds)} | {md_cell(_REWRITE_TEXT[r.match.rewrite])}"
            f"{_claim(_REWRITE_CLAIMS[r.match.rewrite])} | {resolves} |"
        )
    out.append("")
    for r in rules:
        out += [
            f"### {r.id}",
            "",
            f"{md_text(r.feature)}. {md_text(r.reason)}",
            "",
            f"Documentation: {md_text(r.docs)}.",
            "",
        ]
    return out


def _bonus_text(support: EngineSupport) -> str:
    """What a table showing the pattern adds to the engine's table-level score (#921)."""
    parts = []
    if support.table_bonus:
        parts.append(f"{support.table_bonus:+d} pattern match")
    if support.complexity_bonus:
        parts.append(f"{support.complexity_bonus:+d} complexity")
    text = ""
    if parts:
        text = "Table bonus: " + ", ".join(parts)
        if support.bonus_group:
            text += f" (once for the `{support.bonus_group}` group)"
        text += "."
    if support.complexity_feature:
        text += (" " if text else "") + "Counts toward the engine's feature complexity bonus."
    return text


def _threshold_rows(owner: str, thresholds: dict) -> list[str]:
    return [
        f"| {md_cell(owner)} | `{name}` | {t.value:g} | {md_cell(t.why)} |"
        for name, t in thresholds.items()
    ]


def _engine_rule_rows(entries: tuple[EngineEntry, ...]) -> list[str]:
    """The engine-specific routing rules the engine files hold, and the heterogeneous
    Aurora choice's features (#1081)."""
    labels = {e.id: e.display_name for e in entries}
    rows: list[str] = []
    for e in entries:
        if e.status != "active":
            continue
        rules = []
        if e.justification_floor is not None:
            floor = e.justification_floor
            rules.append(
                f"justification floor `{floor.kind}` (ledger reason `{floor.reason_code}`): "
                f"{floor.why}"
            )
        if e.joins_need_denormalized_design:
            rules.append(
                "a join consolidated away from engines none of which is relational or "
                "flagged like this one never lands here (it needs a denormalised design)"
            )
        if e.exact_tie_preferred:
            rules.append(
                "wins an exact heterogeneous Aurora tie no feature breaks, by maintainer rule "
                "(ADR-031 Decision 6 Amendment 1): a named-engine preference held as data"
            )
        rows += [f"| {md_cell(e.display_name)} | {md_cell(rule)} |" for rule in rules]
    features = [
        f"| `{name}` | {md_cell(labels.get(f.favours, f.favours))} | {f.basis} | {md_cell(f.why)} |"
        for name, f in routing_file().heterogeneous_features.items()
    ]
    out: list[str] = []
    if rows:
        out += [
            "",
            "Engine-specific routing rules, each an engine-file field the routing code reads "
            "instead of naming the engine (#1081):",
            "",
            "| Engine | Rule |",
            "|---|---|",
            *rows,
        ]
    if features:
        out += [
            "",
            "The source features that tip a close or tied heterogeneous Aurora call "
            "(`routing.toml`, ADR-031 Decision 6): the choice counts the features on each "
            "side, the workload ones first and the dialect ones only when no workload "
            "feature decides.",
            "",
            "| Feature | Favours | Basis | Why |",
            "|---|---|---|---|",
            *features,
        ]
    return out


def _routing_sections(entries: tuple[EngineEntry, ...]) -> list[str]:
    """The engine routing properties, thresholds, hard gates and triage signals (#921)."""
    out = [
        "",
        "## Engine routing properties",
        "",
        "From each engine file: the source engines whose own dialect it is, whether it "
        "scores a query only on the query's own matched pattern, what the reality check "
        "lets it absorb, whether a signal override onto it needs the justification floor, "
        "and the complexity points for 1, 2, ... feature patterns.",
        "",
        "| Engine | Source engines | Pattern only | Absorbs only | Override needs "
        "justification | Complexity by feature count |",
        "|---|---|---|---|---|---|",
    ]
    for e in entries:
        if e.status != "active":
            continue
        absorbs = "-"
        if e.absorbs_only:
            absorbs = ", ".join(
                [*(f"signal `{x}`" for x in e.absorbs_only.signals)]
                + [f"capability `{x}`" for x in e.absorbs_only.capabilities]
            )
        out.append(
            f"| {md_cell(e.display_name)} | "
            + (", ".join(f"`{x}`" for x in e.source_engines) or "-")
            + f" | {'yes' if e.pattern_only else 'no'} | {absorbs} | "
            f"{'yes' if e.override_needs_justification else 'no'} | "
            + (", ".join(str(x) for x in e.complexity_by_feature_count) or "-")
            + " |"
        )
    out += _engine_rule_rows(entries)
    out += [
        "",
        "## Thresholds",
        "",
        "The routing thresholds and floors: shared ones from `src/catalog/routing.toml`, "
        "an engine's own from its file's `[thresholds.<name>]`.",
        "",
        "| Applies to | Threshold | Value | Why |",
        "|---|---|---|---|",
        *_threshold_rows("Every engine", routing_file().thresholds),
    ]
    for e in entries:
        out += _threshold_rows(e.display_name, e.thresholds)
    gates = gates_file()
    out += [
        "",
        "## Hard gates",
        "",
        "From `src/catalog/gates.toml` (ADR-031 Decision 2 steps 2 and 3). An engine "
        "without a capability cannot serve a query that needs it: one showing a listed "
        "query fact or triage signal. A capability linked to a pattern capability names "
        "the same engines as those pattern files' `supported` flags (the loader checks it).",
        "",
        "| Capability | Engines | Query facts | Triage signals | Pattern capability | Why |",
        "|---|---|---|---|---|---|",
    ]
    names = {e.id: e.display_name for e in entries}
    for cap, c in gates.capabilities.items():
        out.append(
            f"| `{cap}` | "
            + md_cell(", ".join(names.get(x, x) for x in c.engines))
            + " | "
            + (", ".join(f"`{x}`" for x in c.facts) or "structural")
            + " | "
            + (", ".join(f"`{x}`" for x in c.triage_signals) or "-")
            + f" | {f'`{c.pattern_capability}`' if c.pattern_capability else '-'} | "
            f"{md_cell(c.why)} |"
        )
    out += [
        "",
        "Exclusions, checked in order: the engine cannot serve a query showing the fact.",
        "",
        "| Engine | Rule | Fact | Why (technical) | What a rejected override says |",
        "|---|---|---|---|---|",
    ]
    for r in gates.exclusions:
        fact = f"`{r.fact}`" + (f" >= {r.min}" if r.min is not None else "")
        out.append(
            f"| {md_cell(names.get(r.engine, r.engine))} | `{r.rule_id}` | {fact} | "
            f"{md_cell(r.description)} | {md_cell(r.customer_message)} |"
        )
    out += [
        "",
        "Waivers (ADR-031 Decision 2 Amendment 12): the engine serves a capability it lacks "
        "for a query showing the class fact, when the condition holds. The shared scorer "
        "still decides whether the engine wins.",
        "",
        "| Engine | Rule | Capability | Class fact | When | Why |",
        "|---|---|---|---|---|---|",
    ]
    for w in gates.waivers:
        when = "the query's table has its source of truth (its writes) on the engine"
        out.append(
            f"| {md_cell(names.get(w.engine, w.engine))} | `{w.rule_id}` | `{w.capability}` | "
            f"`{w.fact}` | {when} | {md_cell(w.why)} |"
        )
    out += [
        "",
        "## Triage signals",
        "",
        "From `src/catalog/triage_signals.toml`: the engines each signal is evidence for "
        "(detection stays in `src/agents/referee/triage.py`), and the signal overrides.",
        "",
        "| Signal | Targets | Override engine | Override rule |",
        "|---|---|---|---|",
    ]
    for name, sig in triage_signals_file().signals.items():
        out.append(
            f"| `{name}` | "
            + (md_cell(", ".join(names.get(x, x) for x in sig.targets)) or "-")
            + f" | {md_cell(names.get(sig.override_engine, sig.override_engine)) if sig.override_engine else '-'}"
            + f" | {f'`{sig.override_reason_code}`' if sig.override_reason_code else '-'} |"
        )
    return out


def _outputs() -> list[tuple[Path, str]]:
    return [
        (JS_OUT, render_js(engines())),
        (MD_OUT, render_md(engines(), patterns())),
    ]


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--check", action="store_true", help="exit 1 if a file is stale")
    args = parser.parse_args(argv)
    try:
        outputs = _outputs()
    except CatalogError as exc:
        print(f"invalid catalog: {exc}")
        return 1
    if args.check:
        stale = [
            path.relative_to(REPO_ROOT).as_posix()
            for path, expected in outputs
            if (path.read_text(encoding="utf-8") if path.exists() else "") != expected
        ]
        if stale:
            print(f"{', '.join(stale)} out of date. Run: uv run python scripts/render_catalog.py")
            return 1
        print(json.dumps({"render_catalog": "up to date"}))
        return 0
    for path, expected in outputs:
        path.write_text(expected, encoding="utf-8")
    print(json.dumps({"wrote": [path.relative_to(REPO_ROOT).as_posix() for path, _ in outputs]}))
    return 0


if __name__ == "__main__":
    sys.exit(main())
